typedef struct {
    int id;
    char* internal_buffer;
} ResourceObject;

// Constructor/Allocator
ResourceObject* Resource_init(int size) {
    ResourceObject* obj = malloc(sizeof(ResourceObject));
    obj->id = 1;
    obj->internal_buffer = malloc(size);
    return obj;
}

// Destructor/Deallocator
void Resource_destroy(ResourceObject* obj) {
    if (!obj) return;
    // 1. Release internal resources first
    free(obj->internal_buffer);
    // 2. Release the object container last
    free(obj);
}
